    50→/**
    51→ * This class supposed to implement gossip validation rules as per <a
    52→ * href="https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#data_column_sidecar_subnet_id">spec</a>
    53→ */
    54→public class DataColumnSidecarGossipValidator {
    55→  private static final Logger LOG = LogManager.getLogger();
    56→  public static final BiFunction<MetricsSystem, TimeProvider, MetricsHistogram>
    57→      DATA_COLUMN_SIDECAR_INCLUSION_PROOF_VERIFICATION_HISTOGRAM =
    58→          (metricsSystem, timeProvider) ->
    59→              new MetricsHistogram(
    60→                  metricsSystem,
    61→                  timeProvider,
    62→                  TekuMetricCategory.BEACON,
    63→                  "data_column_sidecar_inclusion_proof_verification_seconds",
    64→                  "Time taken to verify data column sidecar inclusion proof",
    65→                  0.001,
    66→                  0.002,
    67→                  0.003,
    68→                  0.004,
    69→                  0.005,
    70→                  0.01,
    71→                  0.015,
    72→                  0.02,
    73→                  0.025,
    74→                  0.03,
    75→                  0.04,
    76→                  0.05,
    77→                  0.1,
    78→                  0.5,
    79→                  1.0);
    80→  public static final BiFunction<MetricsSystem, TimeProvider, MetricsHistogram>
    81→      DATA_COLUMN_SIDECAR_KZG_BATCH_VERIFICATION_HISTOGRAM =
    82→          (metricsSystem, timeProvider) ->
    83→              new MetricsHistogram(
    84→                  metricsSystem,
    85→                  timeProvider,
    86→                  TekuMetricCategory.BEACON,
    87→                  "kzg_verification_data_column_batch_seconds",
    88→                  "Runtime of batched data column kzg verification",
    89→                  0.005,
    90→                  0.01,
    91→                  0.025,
    92→                  0.05,
    93→                  0.075,
    94→                  0.1,
    95→                  0.25,
    96→                  0.5,
    97→                  0.75,
    98→                  1.0,
    99→                  1.25,
   100→                  1.5,
   101→                  1.75,
   102→                  2.0);
   103→
   104→  private final Spec spec;
   105→  private final Set<SlotProposerIndexAndColumnIndex> receivedValidDataColumnSidecarInfoSet;
   106→  private final Set<InclusionProofInfo> validInclusionProofInfoSet;
   107→  private final Set<Bytes32> validSignedBlockHeaders;
   108→  private final GossipValidationHelper gossipValidationHelper;
   109→  private final Map<Bytes32, BlockImportResult> invalidBlockRoots;
   110→  private final MiscHelpersFulu miscHelpersFulu;
   111→  private final KZG kzg;
   112→  private final Counter totalDataColumnSidecarsProcessingRequestsCounter;
   113→  private final Counter totalDataColumnSidecarsProcessingSuccessesCounter;
   114→  private final MetricsHistogram dataColumnSidecarInclusionProofVerificationTimeSeconds;
   115→  private final MetricsHistogram dataColumnSidecarKzgBatchVerificationTimeSeconds;
   116→
   117→  public static DataColumnSidecarGossipValidator create(
   118→      final Spec spec,
   119→      final Map<Bytes32, BlockImportResult> invalidBlockRoots,
   120→      final GossipValidationHelper validationHelper,
   121→      final MiscHelpersFulu miscHelpersFulu,
   122→      final KZG kzg,
   123→      final MetricsSystem metricsSystem,
   124→      final TimeProvider timeProvider) {
   125→
   126→    final Optional<Integer> maybeNumberOfColumns = spec.getNumberOfDataColumns();
   127→
   128→    final int validInfoSize = VALID_BLOCK_SET_SIZE * maybeNumberOfColumns.orElse(1);
   129→    // It's not fatal if we miss something and we don't need finalized data
   130→    final int validSignedBlockHeadersSize =
   131→        spec.getGenesisSpec().getSlotsPerEpoch() * BEST_CASE_NON_FINALIZED_EPOCHS;
   132→
   133→    return new DataColumnSidecarGossipValidator(
   134→        spec,
   135→        invalidBlockRoots,
   136→        validationHelper,
   137→        miscHelpersFulu,
   138→        kzg,
   139→        metricsSystem,
   140→        timeProvider,
   141→        LimitedSet.createSynchronized(validInfoSize),
   142→        LimitedSet.createSynchronized(validSignedBlockHeadersSize),
   143→        LimitedSet.createSynchronized(validSignedBlockHeadersSize));
   144→  }
   145→
   146→  @VisibleForTesting
   147→  public Set<SlotProposerIndexAndColumnIndex> getReceivedValidDataColumnSidecarInfoSet() {
   148→    return receivedValidDataColumnSidecarInfoSet;
   149→  }
   150→
   151→  private DataColumnSidecarGossipValidator(
   152→      final Spec spec,
   153→      final Map<Bytes32, BlockImportResult> invalidBlockRoots,
   154→      final GossipValidationHelper gossipValidationHelper,
   155→      final MiscHelpersFulu miscHelpersFulu,
   156→      final KZG kzg,
   157→      final MetricsSystem metricsSystem,
   158→      final TimeProvider timeProvider,
   159→      final Set<SlotProposerIndexAndColumnIndex> receivedValidDataColumnSidecarInfoSet,
   160→      final Set<InclusionProofInfo> validInclusionProofInfoSet,
   161→      final Set<Bytes32> validSignedBlockHeaders) {
   162→    this.spec = spec;
   163→    this.invalidBlockRoots = invalidBlockRoots;
   164→    this.gossipValidationHelper = gossipValidationHelper;
   165→    this.miscHelpersFulu = miscHelpersFulu;
   166→    this.kzg = kzg;
   167→    this.receivedValidDataColumnSidecarInfoSet = receivedValidDataColumnSidecarInfoSet;
   168→    this.totalDataColumnSidecarsProcessingRequestsCounter =
   169→        metricsSystem.createCounter(
   170→            TekuMetricCategory.BEACON,
   171→            "data_column_sidecar_processing_requests_total",
   172→            "Total number of data column sidecars submitted for processing");
   173→    this.totalDataColumnSidecarsProcessingSuccessesCounter =
   174→        metricsSystem.createCounter(
   175→            TekuMetricCategory.BEACON,
   176→            "data_column_sidecar_processing_successes_total",
   177→            "Total number of data column sidecars verified for gossip");
   178→    this.dataColumnSidecarInclusionProofVerificationTimeSeconds =
   179→        DATA_COLUMN_SIDECAR_INCLUSION_PROOF_VERIFICATION_HISTOGRAM.apply(
   180→            metricsSystem, timeProvider);
   181→    this.dataColumnSidecarKzgBatchVerificationTimeSeconds =
   182→        DATA_COLUMN_SIDECAR_KZG_BATCH_VERIFICATION_HISTOGRAM.apply(metricsSystem, timeProvider);
   183→
   184→    this.validInclusionProofInfoSet = validInclusionProofInfoSet;
   185→    this.validSignedBlockHeaders = validSignedBlockHeaders;
   186→  }
   187→
   188→  public SafeFuture<InternalValidationResult> validate(final DataColumnSidecar dataColumnSidecar) {
   189→    final BeaconBlockHeader blockHeader =
   190→        dataColumnSidecar.getSignedBeaconBlockHeader().getMessage();
   191→
   192→    totalDataColumnSidecarsProcessingRequestsCounter.inc();
   193→
   194→    /*
   195→     * [REJECT] The sidecar is valid as verified by verify_data_column_sidecar(sidecar).
   196→     */
   197→    if (!miscHelpersFulu.verifyDataColumnSidecar(dataColumnSidecar)) {
   198→      return completedFuture(reject("DataColumnSidecar has invalid structure"));
   199→    }
   200→
   201→    /*
   202→     * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, sidecar.index) with valid header signature, sidecar inclusion proof, and kzg proof.
   203→     */
   204→    if (!isFirstValidForSlotProposerIndexAndColumnIndex(dataColumnSidecar, blockHeader)) {
   205→      LOG.trace(
   206→          "DataColumnSidecar is not the first valid for its slot and index. It will be dropped.");
   207→      return completedFuture(InternalValidationResult.IGNORE);
   208→    }
   209→
   210→    /*
   211→     * [REJECT] The sidecar is for the correct subnet -- i.e. compute_subnet_for_data_column_sidecar(sidecar.index) == subnet_id.
   212→     * Already done in {@link tech.pegasys.teku.networking.eth2.gossip.topics.topichandlers.DataColumnSidecarTopicHandler.TopicSubnetIdAwareOperationProcessor#process(
   213→     *        DataColumnSidecar, Optional<UInt64>)}
   214→     */
   215→
   216→    /*
   217→     * [IGNORE] The sidecar is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance) -- i.e. validate that block_header.slot <= current_slot (a client MAY queue future sidecars for processing at the appropriate slot).
   218→     */
   219→    if (gossipValidationHelper.isSlotFromFuture(blockHeader.getSlot())) {
   220→      LOG.trace("DataColumnSidecar is from the future. It will be saved for future processing.");
   221→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   222→    }
   223→
   224→    /*
   225→     * [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that block_header.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
   226→     */
   227→    if (gossipValidationHelper.isSlotFinalized(blockHeader.getSlot())) {
   228→      LOG.trace("DataColumnSidecar is too old (slot already finalized)");
   229→      return completedFuture(InternalValidationResult.IGNORE);
   230→    }
   231→
   232→    // Optimization: If we have already completely verified DataColumnSidecar with the same
   233→    // SignedBlockHeader, we can skip most steps and jump to shortened validation
   234→    if (validSignedBlockHeaders.contains(
   235→        dataColumnSidecar.getSignedBeaconBlockHeader().hashTreeRoot())) {
   236→      return validateDataColumnSidecarWithKnownValidHeader(dataColumnSidecar, blockHeader);
   237→    }
   238→
   239→    /*
   240→     * [REJECT] The proposer signature of sidecar.signed_block_header, is valid with respect to the block_header.proposer_index pubkey.
   241→     *
   242→     * Verified later after all checks not involving state are passed
   243→     */
   244→
   245→    /*
   246→     * [IGNORE] The sidecar's block's parent (defined by block_header.parent_root) has been seen (via both gossip and non-gossip sources) (a client MAY queue sidecars for processing once the parent block is retrieved).
   247→     */
   248→    if (!gossipValidationHelper.isBlockAvailable(blockHeader.getParentRoot())) {
   249→      LOG.trace(
   250→          "DataColumnSidecar block header parent block is not available. It will be saved for future processing.");
   251→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   252→    }
   253→    final Optional<UInt64> maybeParentBlockSlot =
   254→        gossipValidationHelper.getSlotForBlockRoot(blockHeader.getParentRoot());
   255→    if (maybeParentBlockSlot.isEmpty()) {
   256→      LOG.trace(
   257→          "DataColumnSidecar block header parent block does not exist. It will be saved for future processing");
   258→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   259→    }
   260→    final UInt64 parentBlockSlot = maybeParentBlockSlot.get();
   261→
   262→    /*
   263→     * [REJECT] The sidecar's block's parent (defined by block_header.parent_root) passes validation.
   264→     */
   265→    if (invalidBlockRoots.containsKey(blockHeader.getParentRoot())) {
   266→      return completedFuture(reject("DataColumnSidecar block header has an invalid parent root"));
   267→    }
   268→
   269→    /*
   270→     * [REJECT] The sidecar is from a higher slot than the sidecar's block's parent (defined by block_header.parent_root).
   271→     */
   272→    if (!blockHeader.getSlot().isGreaterThan(parentBlockSlot)) {
   273→      return completedFuture(reject("Parent block slot is after DataColumnSidecar slot"));
   274→    }
   275→
   276→    /*
   277→     * [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's block -- i.e. get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root.
   278→     */
   279→    if (!gossipValidationHelper.currentFinalizedCheckpointIsAncestorOfBlock(
   280→        blockHeader.getSlot(), blockHeader.getParentRoot())) {
   281→      return completedFuture(
   282→          reject("DataColumnSidecar block header does not descend from finalized checkpoint"));
   283→    }
   284→
   285→    /*
   286→     * [REJECT] The sidecar's kzg_commitments field inclusion proof is valid as verified by verify_data_column_sidecar_inclusion_proof(sidecar).
   287→     */
   288→    if (!verifyDataColumnSidecarInclusionProof(dataColumnSidecar)) {
   289→      return completedFuture(reject("DataColumnSidecar inclusion proof validation failed"));
   290→    }
   291→
   292→    /*
   293→     * [REJECT] The sidecar's column data is valid as verified by verify_data_column_sidecar_kzg_proofs(sidecar).
   294→     */
   295→    try (MetricsHistogram.Timer ignored =
   296→        dataColumnSidecarKzgBatchVerificationTimeSeconds.startTimer()) {
   297→      if (!miscHelpersFulu.verifyDataColumnSidecarKzgProofs(kzg, dataColumnSidecar)) {
   298→        return completedFuture(reject("DataColumnSidecar does not pass kzg validation"));
   299→      }
   300→    } catch (final Throwable t) {
   301→      return completedFuture(reject("DataColumnSidecar does not pass kzg validation"));
   302→    }
   303→
   304→    return gossipValidationHelper
   305→        .getParentStateInBlockEpoch(
   306→            parentBlockSlot, blockHeader.getParentRoot(), blockHeader.getSlot())
   307→        .thenApply(
   308→            maybePostState -> {
   309→              /*
   310→               * [REJECT] The sidecar is proposed by the expected proposer_index for the block's slot in the context of the current shuffling (defined by block_header.parent_root/block_header.slot).
   311→               *
   312→               * If the proposer_index cannot immediately be verified against the expected shuffling, the sidecar MAY be queued for later processing while proposers for the block's branch are calculated -- in such a case do not REJECT, instead IGNORE this message.
   313→               */
   314→              if (maybePostState.isEmpty()) {
   315→                LOG.trace(
   316→                    "DataColumnSidecar block header state wasn't available. Must have been pruned by finalized.");
   317→                return InternalValidationResult.IGNORE;
   318→              }
   319→              final BeaconState postState = maybePostState.get();
   320→              if (!gossipValidationHelper.isProposerTheExpectedProposer(
   321→                  blockHeader.getProposerIndex(), blockHeader.getSlot(), postState)) {
   322→                return reject(
   323→                    "DataColumnSidecar block header proposed by incorrect proposer (%s)",
   324→                    blockHeader.getProposerIndex());
   325→              }
   326→
   327→              /*
   328→               * [REJECT] The proposer signature of sidecar.signed_block_header, is valid with respect to the block_header.proposer_index pubkey.
   329→               */
   330→              if (!verifyBlockHeaderSignature(
   331→                  postState, dataColumnSidecar.getSignedBeaconBlockHeader())) {
   332→                return reject("DataColumnSidecar block header signature is invalid");
   333→              }
   334→
   335→              /*
   336→               * Checking it again at the very end because whole method is not synchronized
   337→               *
   338→               * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, sidecar.index) with valid header signature, sidecar inclusion proof, and kzg proof.
   339→               */
   340→              if (!receivedValidDataColumnSidecarInfoSet.add(
   341→                  new SlotProposerIndexAndColumnIndex(
   342→                      blockHeader.getSlot(),
   343→                      blockHeader.getProposerIndex(),
   344→                      dataColumnSidecar.getIndex()))) {
   345→                return ignore(
   346→                    "DataColumnSidecar is not the first valid for its slot and index. It will be dropped.");
   347→              }
   348→
   349→              validSignedBlockHeaders.add(
   350→                  dataColumnSidecar.getSignedBeaconBlockHeader().hashTreeRoot());
   351→              validInclusionProofInfoSet.add(
   352→                  new InclusionProofInfo(
   353→                      dataColumnSidecar.getSszKZGCommitments().hashTreeRoot(),
   354→                      dataColumnSidecar.getKzgCommitmentsInclusionProof().hashTreeRoot(),
   355→                      dataColumnSidecar.getBlockBodyRoot()));
   356→
   357→              totalDataColumnSidecarsProcessingSuccessesCounter.inc();
   358→              return ACCEPT;
   359→            });
   360→  }
   361→
   362→  private SafeFuture<InternalValidationResult> validateDataColumnSidecarWithKnownValidHeader(
   363→      final DataColumnSidecar dataColumnSidecar, final BeaconBlockHeader blockHeader) {
   364→
   365→    // This can be changed between two received DataColumnSidecars from one block, so checking
   366→    /*
   367→     * [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's block -- i.e. get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root.
   368→     */
   369→    if (!gossipValidationHelper.currentFinalizedCheckpointIsAncestorOfBlock(
   370→        blockHeader.getSlot(), blockHeader.getParentRoot())) {
   371→      return completedFuture(
   372→          reject("DataColumnSidecar block header does not descend from finalized checkpoint"));
   373→    }
   374→
   375→    /*
   376→     * [REJECT] The sidecar's kzg_commitments field inclusion proof is valid as verified by verify_data_column_sidecar_inclusion_proof(sidecar).
   377→     */
   378→    if (!verifyDataColumnSidecarInclusionProof(dataColumnSidecar)) {
   379→      return completedFuture(reject("DataColumnSidecar inclusion proof validation failed"));
   380→    }
   381→
   382→    /*
   383→     * [REJECT] The sidecar's column data is valid as verified by verify_data_column_sidecar_kzg_proofs(sidecar).
   384→     */
   385→    try (MetricsHistogram.Timer ignored =
   386→        dataColumnSidecarKzgBatchVerificationTimeSeconds.startTimer()) {
   387→      if (!miscHelpersFulu.verifyDataColumnSidecarKzgProofs(kzg, dataColumnSidecar)) {
   388→        return completedFuture(reject("DataColumnSidecar does not pass kzg validation"));
   389→      }
   390→    } catch (final Throwable t) {
   391→      return completedFuture(reject("DataColumnSidecar does not pass kzg validation"));
   392→    }
   393→
   394→    /*
   395→     * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, sidecar.index) with valid header signature, sidecar inclusion proof, and kzg proof.
   396→     */
   397→    if (!receivedValidDataColumnSidecarInfoSet.add(
   398→        new SlotProposerIndexAndColumnIndex(
   399→            blockHeader.getSlot(), blockHeader.getProposerIndex(), dataColumnSidecar.getIndex()))) {
   400→      return SafeFuture.completedFuture(
